#define A08_SALE_SCHEDULE_DP 1
#include "candidate/policy/sale_schedule_dp.hpp"
#include <iostream>
using namespace triad;using namespace sale_dp;
int main(){for(int item=1;item<=7;item++){int s=int(competitive::ConditionalMarket::saturation(item));std::cout<<item<<" saturation "<<s<<" prices "<<dp7::price(item,s-1)<<","<<dp7::price(item,s)<<"\n";} 
for(int item=1;item<=7;item++)for(int inv:{9900,9950,9980,9990,10000})for(int Q:{1,3,6,10})for(int T:{2,3,5}){Problem p;p.item=item;p.stock=inv;p.quantity=Q;p.steps=T;p.minimum_now=Q/3;p.competition=2;p.demand[T-2]=1+item%3;for(int t=0;t<T;t++)p.rival[t]=(t+item)%3==0?2+item%4:0;if(!supported(p))continue;Quotes q(p);for(int sc=0;sc<4;sc++){bool traffic=sc>0;Ordering o=Ordering(std::max(0,sc-1));auto s=solve(p,q,traffic,o);auto c=evaluate(p,q,s,traffic,o);double score=c.own-p.competition*c.rival,best=-1e100;Schedule bs{},b{};std::function<void(int,int)>dfs=[&](int t,int r){if(t==T-1){b[t]=r;auto bc=evaluate(p,q,b,traffic,o);double z=bc.own-p.competition*bc.rival;if(z>best){best=z;bs=b;}return;}for(int a=t==0?p.minimum_now:0;a<=r;a++){b[t]=a;dfs(t+1,r-a);}};dfs(0,Q);if(std::abs(score-best)>1e-7){std::cout<<"FAIL "<<item<<" "<<inv<<" "<<Q<<" "<<T<<" sc "<<sc<<" nonfloor "<<non_saturating(p)<<" actual "<<score<<" best "<<best<<" chosen ";for(int a:s)std::cout<<a<<",";std::cout<<" brute ";for(int a:bs)std::cout<<a<<",";std::cout<<"\n";return 1;}}}}
